click.script:
const req = myRequirement.data;
settingsCompanyName.value = req ? (req.company_name || '') : '';
settingsCountry.value = req ? (req.country || '') : '';
settingsIndustry.value = req ? (req.industry || '') : '';
settingsApps.value = req ? (req.apps || []) : [];
settingsLookingFor.value = req ? (req.looking_for || '') : '';
settingsCompanySize.value = req ? (req.company_size || '') : '';
settingsCurrentSituation.value = req ? (req.current_situation || '') : '';
settingsTimeline.value = req ? (req.timeline || '') : '';
settingsDeliveryPreference.value = req ? (req.delivery_preference || '') : '';
settingsBudget.value = req ? (req.budget || '') : '';
settingsSpecialRequirements.value = req ? JSON.parse(req.special_requirements || '[]') : [];
settingsOpen.value = true;

if (eventArgs && eventArgs[0]) { eventArgs[0].preventDefault(); eventArgs[0].stopPropagation(); }
const partner = item.name;
const previous = myShortlistFull.data || [];
myShortlistFull.data = previous.filter((p) => p.name !== partner);
call('connect.api.customer.remove_from_shortlist', { partner }).then(() => { myShortlistFull.reload(); }).catch((err) => {
  myShortlistFull.data = previous;
  toast({ title: 'Could not remove from shortlist', text: (err && err.message) || 'Please try again', icon: 'x' });
});

if (!myContext.data || !myContext.data.customer) {
  window.location.href = '/login?redirect-to=' + encodeURIComponent(window.location.pathname);
  return;
}
if (eventArgs && eventArgs[0]) { eventArgs[0].preventDefault(); eventArgs[0].stopPropagation(); }
call('connect.api.contact.start_partner_thread', { partner: item.name }).then((result) => {
  const query = { thread: result && result.thread };
  if (result && result.is_new_thread) query.requirement = '1';
  router.push('/messaging-d87b?' + new URLSearchParams(query).toString());
}).catch((err) => {
  toast({ title: 'Could not start conversation', text: (err && err.message) || 'Please try again', icon: 'x' });
});

